  it('a failure offers Try again, and it works', async () => {
    const user = userEvent.setup();
    render(<AdminBookings client={clientAnswering({ status: 500, data: {} }, { status: 200, data: [ROW] })} />);
    await user.click(await screen.findByRole('button', { name: 'Try again' }));
    expect(await screen.findByRole('table')).toBeInTheDocument();
  });
});

import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { BookingForm } from './BookingForm.jsx';
import { fillBooking, deferred } from './support.jsx';

const created = (status) => ({ status: 201, data: { id: 1, lab: 'BE-201', status } });
const failed = (status, code) => ({ status, data: { error: { code } } });

function setup(onSubmit = vi.fn().mockResolvedValue(created('CONFIRMED'))) {
  const user = userEvent.setup();
  render(<BookingForm onSubmit={onSubmit} />);
  const book = () => user.click(screen.getByRole('button', { name: 'Book' }));
  return { user, onSubmit, book };
}

describe('BookingForm', () => {
  it('every field is reachable by its label', () => {
    setup();
    for (const name of ['Lab', 'Date', 'Start', 'End', 'Seats']) expect(screen.getByLabelText(name)).toBeInTheDocument();
  });

  it('sends what the user typed, once, and says it is booked', async () => {
    const { user, onSubmit, book } = setup();
    await fillBooking(user);
    await book();
    expect(onSubmit).toHaveBeenCalledExactlyOnceWith({ lab: 'BE-201', date: '2026-11-16', start: '08:00', end: '10:00', seats: 20 });
    expect(await screen.findByRole('status')).toHaveTextContent('Booked. See you in BE-201.');
  });

  it('a PENDING booking says it waits for approval', async () => {
    const { user, book } = setup(vi.fn().mockResolvedValue(created('PENDING')));
    await fillBooking(user, { seats: '31' });
    await book();
    expect(await screen.findByRole('status')).toHaveTextContent('Sent. A lecturer must approve this booking.');
  });

  it.each([
    ['0', true], ['1', false], ['200', false], ['201', true],
  ])('seats %s → refused in the browser: %s', async (seats, refused) => {
    const { user, onSubmit, book } = setup();
    await fillBooking(user, { seats });
    await book();
    expect(screen.getByRole('spinbutton', { name: 'Seats' }).getAttribute('aria-invalid') === 'true').toBe(refused);
    expect(onSubmit).toHaveBeenCalledTimes(refused ? 0 : 1);
  });

  it('while waiting, the button is disabled and a second click sends nothing', async () => {
    const answer = deferred();
    const { user, onSubmit, book } = setup(vi.fn(() => answer.promise));
    await fillBooking(user);
    await book();
    await user.click(screen.getByRole('button', { name: 'Booking…' }));
    expect(onSubmit).toHaveBeenCalledTimes(1);
    answer.resolve(created('CONFIRMED'));
    expect(await screen.findByRole('button', { name: 'Book' })).toBeEnabled();
  });

  it('a 400 from the server is shown on its field', async () => {
    const { user, book } = setup(vi.fn().mockResolvedValue({ status: 400, data: { error: { code: 'VALIDATION', details: [{ path: 'date', message: 'Invalid ISO date' }] } } }));
    await fillBooking(user);
    await book();
    expect(await screen.findByLabelText('Date')).toHaveAccessibleDescription('Invalid ISO date');
  });

  it.each([
    [409, 'OVERLAP', 'This slot is already taken. Choose another time.'],
    [422, 'TOO_LONG', 'A booking can last at most 4 hours.'],
    [500, 'INTERNAL', 'Something went wrong. Try again.'],
  ])('%i %s → an alert users hear', async (status, code, text) => {
    const { user, book } = setup(vi.fn().mockResolvedValue(failed(status, code)));
    await fillBooking(user);
    await book();
    expect(await screen.findByRole('alert')).toHaveTextContent(text);
  });
});

// US-11 "My bookings" — the screen (Chapter 11). A stub client, like AdminBookings.test.jsx: no server, no network.
import { describe, it, expect, vi } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MyBookings } from './MyBookings.jsx';
import { ROW, deferred } from './support.jsx';

const LATER = { ...ROW, id: 2, lab: 'BE-305', start: '13:00', end: '15:00' };
const GONE = { ...ROW, id: 3, lab: 'AL-101', status: 'CANCELLED' };
const cancelButton = (b) => screen.getByRole('button', { name: 'Cancel ' + b.lab + ' on ' + b.date + ' at ' + b.start });

// listMine answers once with these rows; cancelBooking answers with `answer` (a value, or a function of the id).
function client(rows, answer) {
  return {
    listMine: vi.fn(async () => ({ status: 200, data: rows })),
    cancelBooking: vi.fn(async (id) => (typeof answer === 'function' ? answer(id) : answer)),
  };
}

describe('MyBookings screen (US-11)', () => {
  it('one row per booking; a cancelled one has no Cancel button (AC1)', async () => {
    render(<MyBookings client={client([ROW, LATER, GONE])} />);
    const table = await screen.findByRole('table', { name: 'My bookings' });
    expect(within(table).getAllByRole('row')).toHaveLength(4);
    expect(within(table).getAllByRole('button')).toHaveLength(2);
    expect(within(table).getByRole('row', { name: /AL-101/ })).toHaveTextContent('CANCELLED');
  });

  it('Cancel → the row says CANCELLED, the button is gone, and the user is told (AC2)', async () => {
    const user = userEvent.setup();
    const api = client([ROW, LATER], (id) => ({ status: 200, data: { ...ROW, id, status: 'CANCELLED' } }));
    render(<MyBookings client={api} />);
    await user.click(await screen.findByRole('button', { name: 'Cancel BE-201 on 2026-11-16 at 08:00' }));
    expect(await screen.findByRole('status')).toHaveTextContent('Cancelled BE-201 on 2026-11-16, 08:00–10:00.');
    expect(screen.getByRole('row', { name: /BE-201/ })).toHaveTextContent('CANCELLED');
    expect(screen.queryByRole('button', { name: /^Cancel BE-201/ })).not.toBeInTheDocument();
    expect(api.cancelBooking).toHaveBeenCalledWith(1);
  });

  it('while cancelling: “Cancelling…”, every Cancel disabled, one request for a double click', async () => {
    const user = userEvent.setup();
    const answer = deferred();
    const api = client([ROW, LATER], () => answer.promise);
    render(<MyBookings client={api} />);
    const button = await screen.findByRole('button', { name: /^Cancel BE-201/ });
    await user.dblClick(button);
    expect(button).toHaveTextContent('Cancelling…');
    expect(button).toBeDisabled();
    expect(cancelButton(LATER)).toBeDisabled();
    answer.resolve({ status: 200, data: { ...ROW, status: 'CANCELLED' } });
    expect(await screen.findByRole('status')).toBeInTheDocument();
    expect(cancelButton(LATER)).toBeEnabled();
    expect(api.cancelBooking).toHaveBeenCalledTimes(1);
  });

  it('422 TOO_LATE_TO_CANCEL → an alert, and the booking stays as it was (AC2)', async () => {
    const user = userEvent.setup();
    render(<MyBookings client={client([ROW], { status: 422, data: { error: { code: 'TOO_LATE_TO_CANCEL' } } })} />);
    await user.click(await screen.findByRole('button', { name: /^Cancel BE-201/ }));
    expect(await screen.findByRole('alert')).toHaveTextContent('Too late to cancel: the booking starts in less than 1 hour.');
    expect(screen.getByRole('row', { name: /BE-201/ })).toHaveTextContent('CONFIRMED');
